export class SingleSerieData implements FlChart2dDatum {
  constructor(private date: Date,
              private value: number) {
  }

  getX(): Date {
    return this.date;
  }

  getY(): number {
    return this.value;
  }

  getXLabel(): string {
    return '';
  }

  getYLabel(): string {
    return this.value.toString();
  }


}

export function getSingleSerieData(): SingleSerieData[] {
  return singleSerie.map(data => new SingleSerieData(new Date(data.date), parseInt(data.value)));
}

